-- TABLA TEMPORAL CON UUID PARA TODAS LAS ENTIDADES
CREATE TEMP TABLE uuid_temp_entities AS
SELECT 
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_user,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_book,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_author,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_publisher,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_review,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_favorite,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_follow,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_reading_list,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_subscription,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_notification,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_promotion,
     md5(random()::text || clock_timestamp()::text || row_number() OVER ())::uuid AS id_ad_campaign,
    row_number() OVER () AS rn
FROM generate_series(1, 100000);

