INSERT INTO public."author" (
    author_id, "name", biography, nationality
)
SELECT 
    u.id_author,
    an.name,
    ab.bio,
    (random() * 229 + 1)::int
FROM uuid_temp_entities u
JOIN (
    SELECT id_author, 
           (random() * 999 + 1)::int as name_rn,
           (random() * 499 + 1)::int as bio_rn
    FROM uuid_temp_entities
) AS random_values ON u.id_author = random_values.id_author
JOIN temp_author_names an ON random_values.name_rn = an.rn
JOIN temp_author_bios ab ON random_values.bio_rn = ab.rn;

