INSERT INTO public."publisher" (
    publisher_id, "name", country_id, founded_year, website, description
)
SELECT 
    u.id_publisher,
    pn.name,
    (random() * 229 + 1)::int, -- País aleatorio entre 1 y 230
    (1800 + random() * 223)::int, -- Año entre 1800 y 2023
    pw.website,
    pd.descripcion
FROM uuid_temp_entities u
JOIN temp_publisher_names pn ON (random() * 999 + 1)::int = pn.rn
JOIN temp_publisher_descs pd ON (random() * 499 + 1)::int = pd.rn
JOIN temp_publisher_websites pw ON (random() * 499 + 1)::int = pw.rn
WHERE u.rn <= 5000;

