INSERT INTO public."user" (
    user_id, "password", "name", profile_picture, is_premium, created_at, user_type
)
SELECT 
    u.id_user,
    encode(gen_random_bytes(16), 'hex'),
    n.nombre_completo,
    NULL,
    CASE WHEN random() < 0.2 THEN true ELSE false END,
    CURRENT_TIMESTAMP - (random() * interval '365 days'),
    CASE 
        WHEN random() < 0.1 THEN 1 -- 10% admin
        WHEN random() < 0.3 THEN 2 -- 20% premium (del 10 al 30%)
        ELSE 3 -- 70% regular
    END
FROM uuid_temp_entities u
JOIN temp_user_names n ON u.rn = n.rn;

-- Verificación de tipos de usuario asignados
SELECT user_type, COUNT(*) FROM "user" GROUP BY user_type ORDER BY user_type;

-- ============ GENERACIÓN DE SUSCRIPCIONES ============
INSERT INTO public."subscription" (
    subscription_id, user_id, plan_type, start_date, end_date, payment_status
)
SELECT 
    u.id_subscription,
    u.id_user,
    (random() * 2 + 1)::int, -- plan_type entre 1 y 3
    CURRENT_DATE - (random() * interval '365 days'),
    CURRENT_DATE + (random() * interval '365 days'),
    CASE 
        WHEN random() < 0.7 THEN 2 -- 70% Pagado
        WHEN random() < 0.85 THEN 1 -- 15% Pendiente
        WHEN random() < 0.95 THEN 3 -- 10% Cancelado
        ELSE 4 -- 5% Rechazado
    END
FROM uuid_temp_entities u
WHERE random() < 0.5; -- 50% de usuarios tienen suscripción

