INSERT INTO public."book" (
    book_id, title, author, synopsis, cover_image, language, is_audiobook, file_url,
    created_at, updated_at, uploaded_by, publisher_id, published_year, isbn
)
SELECT 
    u.id_book,
    b.titulo,
    (SELECT id_author FROM uuid_temp_entities ORDER BY random() LIMIT 1),
    b.sinopsis,
    NULL,
    b.idioma,
    b.es_audiolibro,
    '/books/' || replace(lower(b.titulo), ' ', '_') || CASE WHEN b.es_audiolibro THEN '.mp3' ELSE '.pdf' END,
    CURRENT_TIMESTAMP - (random() * interval '365 days'),
    NULL,
    (SELECT user_id FROM public."user" WHERE user_type = 1 ORDER BY random() LIMIT 1),
    CASE WHEN random() < 0.8 THEN (SELECT publisher_id FROM public."publisher" ORDER BY random() LIMIT 1) ELSE NULL END,
    (CURRENT_DATE - (random() * interval '50 years'))::date,
    CASE WHEN random() < 0.7 THEN NULL ELSE substring(md5(random()::text), 1, 13) END
FROM uuid_temp_entities u
JOIN temp_book_data b ON u.rn = b.rn
ORDER BY random() LIMIT 100000;

