WITH numbered_books AS (
    SELECT book_id, title, ROW_NUMBER() OVER (ORDER BY book_id) as seq_num
    FROM public."book" 
    WHERE is_audiobook = true
),
numbered_narrators AS (
    SELECT narrator, ROW_NUMBER() OVER (ORDER BY narrator) as seq_num
    FROM temp_narrators
),
narrator_count AS (
    SELECT COUNT(*) as total FROM temp_narrators
)
INSERT INTO public."audiobook" (
    book_id, duration, narrator, audio_file_url
)
SELECT 
    b.book_id,
    (60 + random() * 540)::int, -- Duración entre 1 y 10 horas
    n.narrator,
    '/audiobooks/' || replace(lower(b.title), ' ', '_') || '.mp3'
FROM numbered_books b
JOIN numbered_narrators n ON (b.seq_num % (SELECT total FROM narrator_count)) + 1 = n.seq_num;

