INSERT INTO public."review" (
    review_id, rating, "comment", created_at, user_id, book_id
)
WITH 
-- 1. Seleccionar aleatoriamente el 40% de los libros (aproximadamente)
selected_books AS (
    SELECT book_id 
    FROM public."book" 
    WHERE random() < 0.4
    LIMIT (SELECT COUNT(*) * 0.4 FROM public."book")::int
),
-- 2. Para cada libro, seleccionar 5 usuarios aleatorios distintos
book_user_pairs AS (
    SELECT 
        b.book_id,
        (SELECT id_user FROM uuid_temp_entities ORDER BY random() LIMIT 1 OFFSET 0) as user1,
        (SELECT id_user FROM uuid_temp_entities ORDER BY random() LIMIT 1 OFFSET 1) as user2,
        (SELECT id_user FROM uuid_temp_entities ORDER BY random() LIMIT 1 OFFSET 2) as user3,
        (SELECT id_user FROM uuid_temp_entities ORDER BY random() LIMIT 1 OFFSET 3) as user4,
        (SELECT id_user FROM uuid_temp_entities ORDER BY random() LIMIT 1 OFFSET 4) as user5
    FROM selected_books b
),
-- 3. Desnormalizar las parejas a filas individuales
expanded_reviews AS (
    SELECT book_id, user1 as id_user FROM book_user_pairs UNION ALL
    SELECT book_id, user2 FROM book_user_pairs UNION ALL
    SELECT book_id, user3 FROM book_user_pairs UNION ALL
    SELECT book_id, user4 FROM book_user_pairs UNION ALL
    SELECT book_id, user5 FROM book_user_pairs
)
-- 4. Insertar finalmente con todos los datos generados
SELECT 
    gen_random_uuid(),
    (random() * 4 + 1)::int, -- rating 1-5
    CASE WHEN random() < 0.7 THEN 
        (SELECT comment FROM temp_review_comments ORDER BY random() LIMIT 1) 
    ELSE NULL END,
    CURRENT_TIMESTAMP - (random() * interval '180 days'),
    id_user,
    book_id
FROM expanded_reviews;

-- ============ GENERACIÓN DE FAVORITOS ============

INSERT INTO public."favorite" (
    favorite_id, created_at, user_id, book_id
)
SELECT 
    u.id_favorite,
    CURRENT_TIMESTAMP - (random() * interval '90 days'),
    u.id_user,
    u.id_book
FROM uuid_temp_entities u
WHERE random() < 0.3; -- 30% de usuarios marcan libros como favoritos

-- ============ GENERACIÓN DE SEGUIMIENTOS ============
INSERT INTO public."follow" (
    follow_id, created_at, follower_id, followed_id
)
SELECT 
    gen_random_uuid(),  -- Genera un nuevo UUID único para cada relación
    CURRENT_TIMESTAMP - (random() * interval '120 days'),
    u1.id_user,
    u2.id_user
FROM 
    uuid_temp_entities u1
JOIN 
    (SELECT id_user FROM uuid_temp_entities ORDER BY random()) u2 
    ON u1.id_user != u2.id_user  -- Evita que un usuario se siga a sí mismo
WHERE 
    random() < 0.001  -- Ajusta este valor para controlar la densidad de relaciones
LIMIT 
    (SELECT COUNT(id_follow) FROM uuid_temp_entities); 

