-- Tabla temporal con descripciones para listas
CREATE TEMP TABLE temp_list_descriptions AS
SELECT 
    row_number() OVER () AS rn,
    description
FROM (
    VALUES
        ('Cupiditate accusamus explicabo eum dolore totam sunt sapiente.'),
