INSERT INTO public."reading_list" (
    list_id, "name", description, created_by, is_public, created_at
)
SELECT 
    u.id_reading_list,
    'Mi lista ' || substring(md5(random()::text), 1, 6),
    CASE 
        WHEN random() < 0.6 THEN (SELECT description FROM temp_list_descriptions ORDER BY random() LIMIT 1)
        ELSE NULL
    END,
    u.id_user,
    CASE WHEN random() < 0.7 THEN true ELSE false END,
    CURRENT_TIMESTAMP - (random() * interval '60 days')
FROM uuid_temp_entities u
WHERE random() < 0.25;

-- ============ GENERACIÓN DE ITEMS EN LISTAS ============
INSERT INTO public."reading_list_item" (list_id, book_id, added_at)
WITH 
-- 1. Seleccionar listas de lectura aleatorias
random_lists AS (
    SELECT list_id, created_at 
    FROM public."reading_list" 
    WHERE random() < 0.4  -- Ajustar según necesidad
),
-- 2. Seleccionar libros aleatorios
random_books AS (
    SELECT book_id 
    FROM public."book" 
    ORDER BY random() 
    LIMIT 50000
),
-- 3. Generar pares lista-libro de forma eficiente
list_book_pairs AS (
    SELECT 
        r.list_id,
        b.book_id,
        r.created_at + (random() * interval '7 days') as added_at
    FROM random_lists r
    CROSS JOIN LATERAL (
        SELECT book_id 
        FROM random_books 
        ORDER BY random() 
        LIMIT (random() * 10 + 1)::int  -- 1-10 libros por lista
    ) b
)
SELECT list_id, book_id, added_at FROM list_book_pairs;

-- ============ GENERACIÓN DE NOTIFICACIONES ============
-- Consulta de inserción corregida
INSERT INTO public."notification" (
    notification_id, message, is_read, created_at, user_id, notification_type
)
WITH 
-- Seleccionar usuarios aleatorios (ajustar LIMIT según necesidad)
selected_users AS (
    SELECT id_user 
    FROM uuid_temp_entities 
    ORDER BY random() 
    LIMIT 10000
),
-- Generar combinaciones usuario-tipo de notificación
user_notification_combinations AS (
    SELECT 
        u.id_user,
        nt.notification_type_id,
        ROW_NUMBER() OVER () as seq_num
    FROM selected_users u
    CROSS JOIN (SELECT notification_type_id FROM public."notification_type") nt
    WHERE random() < 0.3  -- Probabilidad ajustada para obtener más registros
)
SELECT 
    gen_random_uuid(),  -- Generar nuevo UUID único
    CASE notification_type_id
        WHEN 1 THEN 'Nuevo libro disponible: ' || substring(md5(random()::text), 1, 10)
        WHEN 2 THEN 'Recordatorio: Continúa leyendo ' || substring(md5(random()::text), 1, 10)
        WHEN 3 THEN 'Promoción especial: ' || substring(md5(random()::text), 1, 15)
        ELSE substring(md5(random()::text), 1, 10) || ' ha empezado a seguirte'
    END,
    CASE WHEN seq_num % 3 = 0 THEN true ELSE false END,  -- Alternar is_read
    CURRENT_TIMESTAMP - (seq_num * interval '1 hour'),  -- Fechas escalonadas
    id_user,
    notification_type_id
FROM user_notification_combinations;

-- ============ GENERACIÓN DE MÉTRICAS DE LIBROS ============
INSERT INTO public."book_metrics" (
    book_id, total_reads, total_listens, total_favorites, total_reviews, 
    average_rating, last_read_at, updated_at
)
WITH 
-- Agregar estadísticas de favoritos
favorite_counts AS (
    SELECT 
        book_id, 
        COUNT(*) as fav_count
    FROM public."favorite"
    GROUP BY book_id
),
-- Agregar estadísticas de reseñas
review_stats AS (
    SELECT 
        book_id, 
        COUNT(*) as review_count,
        AVG(rating) as avg_rating
    FROM public."review"
    GROUP BY book_id
)
SELECT 
    b.book_id,
    (random() * 10000)::int as total_reads,
    CASE WHEN b.is_audiobook THEN (random() * 5000)::int ELSE 0 END as total_listens,
    COALESCE(f.fav_count, 0) as total_favorites,
    COALESCE(r.review_count, 0) as total_reviews,
	CASE 
	    WHEN r.review_count > 0 THEN 
	        LEAST(GREATEST((random() * 3 + 2)::numeric(3,1), 2.0), 5.0)
	    ELSE 0::numeric(3,1)
	END as average_rating,
    CURRENT_TIMESTAMP - (random() * interval '7 days') as last_read_at,
    CURRENT_TIMESTAMP as updated_at
FROM public."book" b
LEFT JOIN favorite_counts f ON b.book_id = f.book_id
LEFT JOIN review_stats r ON b.book_id = r.book_id;

-- ============ GENERACIÓN DE PROMOCIONES ============
INSERT INTO public."promotion" (
    promotion_id, book_id, title, description, start_date, end_date, discount_percent, banner_image_url, created_at
)
SELECT 
    u.id_promotion,
    b.book_id,
    'Promoción de ' || substring(b.title, 1, 20),
    'No te pierdas esta oferta especial en ' || b.title,
    CURRENT_DATE,
    CURRENT_DATE + (random() * interval '30 days'),
    (random() * 50 + 10)::int, -- Descuento entre 10% y 60%
    '/banners/' || substring(md5(random()::text), 1, 10) || '.jpg',
    CURRENT_TIMESTAMP
FROM 
    (SELECT book_id, title FROM public."book" ORDER BY random() LIMIT 10000) b,
    uuid_temp_entities u
WHERE u.rn <= 10000;

-- ============ GENERACIÓN DE CAMPAÑAS PUBLICITARIAS ============
INSERT INTO public."ad_campaign" (
    ad_id, title, image_url, target_url, book_id, created_by, 
    visible_to_plan, start_date, end_date, impressions, clicks, created_at
)
SELECT 
    gen_random_uuid(), -- Genera un UUID único para cada campaña
    'Descubre: ' || substring(b.title, 1, 15),
    '/ads/' || substring(md5(random()::text), 1, 10) || '.jpg',
    '/book/' || b.book_id,
    b.book_id,
    (SELECT user_id FROM public."user" WHERE user_type = 1 ORDER BY random() LIMIT 1),
    (random() * 2 + 1)::int, -- plan_type entre 1 y 3
    CURRENT_DATE - (random() * interval '15 days'),
    CURRENT_DATE + (random() * interval '30 days'),
    (random() * 100000)::int,
    (random() * 1000)::int,
    CURRENT_TIMESTAMP - (random() * interval '20 days')
FROM 
    (SELECT book_id, title FROM public."book" ORDER BY random() LIMIT 5000) b;

-- ============ GENERACIÓN DE USER_BOOK ============
INSERT INTO public."user_book" (
    user_id, book_id, pages_read, minutes_listened, last_accessed
)
SELECT 
    u.id_user,
    u.id_book,
    CASE WHEN b.is_audiobook THEN 0 ELSE (random() * 500)::int END,
    CASE WHEN b.is_audiobook THEN (random() * COALESCE(ab.duration, 0))::int ELSE 0 END,
    CURRENT_TIMESTAMP - (random() * interval '30 days')
FROM uuid_temp_entities u
JOIN public."book" b ON u.id_book = b.book_id
LEFT JOIN public."audiobook" ab ON b.book_id = ab.book_id
WHERE random() < 0.7; -- 70% de usuarios tendrán al menos un libro

-- ============ GENERACIÓN DE GÉNEROS DE LIBROS ============
INSERT INTO public."genre_book" (
    book_id, genre_type_id
)
WITH libros_con_generos AS (
    SELECT 
        b.book_id,
        gt.genre_type_id,
        row_number() OVER (PARTITION BY b.book_id ORDER BY random()) as rn
    FROM 
        public."book" b
    CROSS JOIN 
        public."genre_type" gt
    WHERE random() < 0.7 -- 70% de probabilidad de asignar género
)
SELECT 
    book_id,
    genre_type_id
FROM 
    libros_con_generos
WHERE 
    rn <= 3; -- Máximo 3 géneros por libro

-- ============ GENERACIÓN DE ETIQUETAS DE LIBROS ============
INSERT INTO public."book_tag" (
    book_id, tag_id
)
WITH libros_con_etiquetas AS (
    SELECT 
        b.book_id,
        t.tag_id,
        row_number() OVER (PARTITION BY b.book_id ORDER BY random()) as rn
    FROM 
        public."book" b
    CROSS JOIN 
        public."tag" t
    WHERE random() < 0.5 -- 50% de probabilidad de asignar etiqueta
)
SELECT 
    book_id,
    tag_id
FROM 
    libros_con_etiquetas
WHERE 
    rn <= 2; -- Máximo 2 etiquetas por libro

-- ============ GENERACIÓN DE SIMILITUD ENTRE LIBROS ============
INSERT INTO public."book_similarity" (
    book_id_1, book_id_2, similarity_score
)
WITH pares_libros AS (
    SELECT 
        b1.book_id as book_id_1,
        b2.book_id as book_id_2
    FROM 
        (SELECT book_id FROM public."book" ORDER BY random() LIMIT 10000) b1
    CROSS JOIN 
        (SELECT book_id FROM public."book" ORDER BY random() LIMIT 10000) b2
    WHERE 
        b1.book_id != b2.book_id
        AND random() < 0.1 -- 10% de probabilidad de crear relación
)
SELECT 
    book_id_1,
    book_id_2,
    (random() * 0.9 + 0.1)::numeric(3,2) -- Score entre 0.1 y 1.0
FROM 
    pares_libros
LIMIT 5000; -- Limitar a 50,000 relaciones de similitud

-- Limpieza de tablas temporales
DROP TABLE IF EXISTS uuid_temp_entities;
DROP TABLE IF EXISTS temp_user_names;
DROP TABLE IF EXISTS temp_book_data;

